import { styled, View } from '@tamagui/web';

import type { ThrobberContract } from './Throbber.contract';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { openStyle } from '../../helpers/openStyle';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebDivProps } from '../../types/WebElementProps';

export type ThrobberProps = WebDivProps<ThrobberContract>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const throbberFrame = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'flex',
	justifyContent: 'center',
	marginBlock: -1,
} as const;

const throbberCircle = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	marginInline: 1,
	borderRadius: '100%',
} as const;

const throbberSizes = {
	x8: {
		width: '$size.x8',
		height: '$size.x8',
	},
	x12: {
		width: '$size.x12',
		height: '$size.x12',
	},
	x16: {
		width: '$size.x16',
		height: '$size.x16',
	},
	x20: {
		width: '$size.x20',
		height: '$size.x20',
	},
	x24: {
		width: '$size.x24',
		height: '$size.x24',
	},
	x32: {
		width: '$size.x32',
		height: '$size.x32',
	},
	x40: {
		width: '$size.x40',
		height: '$size.x40',
	},
} as const;

const throbberTones = {
	primary: {
		backgroundColor: '$rcx-button-background-primary-default',
	},
	muted: {
		backgroundColor: '$rcx-button-background-secondary-default',
	},
	inherit: {
		backgroundColor: 'currentColor',
	},
} as const;

// end of generated

const ThrobberFrame = styled(View, { render: 'div', ...throbberFrame });

const CircleFrame = styled(View, {
	render: 'span',
	...throbberCircle,
	variants: {
		sizing: throbberSizes,
		tone: throbberTones,
	},
});

/**
 * Indicates content that has not loaded yet.
 */
function Throbber(props: ThrobberProps) {
	const { disabled, size = 'x16', circleCount = 3, inheritColor, className } = props;
	const count = circleCount || 3;
	const modifiers = `${disabled ? ' rcx-throbber__circle--disabled' : ''}${inheritColor ? ' rcx-throbber__circle--inherit-color' : ''}`;

	return (
		<ThrobberFrame
			className={prependClassName(className, 'rcx-box rcx-box--full rcx-throbber')}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} role={props.role} />}
		>
			{Array.from({ length: count }, (_, iteration) => (
				<CircleFrame
					key={iteration}
					sizing={size}
					tone={(inheritColor && 'inherit') || (disabled && 'muted') || 'primary'}
					className={`rcx-box rcx-box--full rcx-throbber__circle${modifiers}`}
					// Each circle starts after the one before it, and a cycle lasts longer the more circles there are
					render={<span {...openStyle({ animationDuration: `${count * 0.466}s`, animationDelay: `${iteration * 0.16}s` })} />}
				/>
			))}
		</ThrobberFrame>
	);
}

export default Throbber;
